413	        }
414	        String national = digits.substring(countryCode.length());
415	        StringBuilder display = new StringBuilder("+").append(countryCode);
416	        for (int i = 0; i < national.length(); i += 3) {
417	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
